#include <string>
#include <vector>

class Solution {
public:
    std::string entityParser(std::string text) {
        std::vector<std::pair<std::string, std::string>> entities = {
            {"&quot;", "\""},
            {"&apos;", "'"},
            {"&amp;", "&"},
            {"&gt;", ">"},
            {"&lt;", "<"},
            {"&frasl;", "/"}
        };
        std::string res = "";
        int i = 0, n = text.size();
        while (i < n) {
            bool matched = false;
            if (text[i] == '&') {
                for (const auto& [ent, ch] : entities) {
                    if (text.substr(i, ent.size()) == ent) {
                        res += ch;
                        i += ent.size();
                        matched = true;
                        break;
                    }
                }
            }
            if (!matched) {
                res += text[i++];
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String entityParser(String text) {
        Map<String, String> entities = new LinkedHashMap<>();
        entities.put("&quot;", "\"");
        entities.put("&apos;", "'");
        entities.put("&amp;", "&");
        entities.put("&gt;", ">");
        entities.put("&lt;", "<");
        entities.put("&frasl;", "/");
        StringBuilder res = new StringBuilder();
        int i = 0, n = text.length();
        while (i < n) {
            boolean matched = false;
            if (text.charAt(i) == '&') {
                for (Map.Entry<String, String> e : entities.entrySet()) {
                    String ent = e.getKey();
                    if (text.startsWith(ent, i)) {
                        res.append(e.getValue());
                        i += ent.length();
                        matched = true;
                        break;
                    }
                }
            }
            if (!matched) {
                res.append(text.charAt(i++));
            }
        }
        return res.toString();
    }
}

var entityParser = function(text) {
    const entities = [
        ['&quot;', '"'],
        ['&apos;', "'"],
        ['&amp;', '&'],
        ['&gt;', '>'],
        ['&lt;', '<'],
        ['&frasl;', '/']
    ];
    const res = [];
    let i = 0;
    while (i < text.length) {
        let matched = false;
        if (text[i] === '&') {
            for (const [ent, ch] of entities) {
                if (text.startsWith(ent, i)) {
                    res.push(ch);
                    i += ent.length;
                    matched = true;
                    break;
                }
            }
        }
        if (!matched) {
            res.push(text[i++]);
        }
    }
    return res.join('');
};
